package dev.veltraph.client.builder;

import dev.veltraph.client.gui.MenuSnapshot;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class GeneratedResourceRuntimeTest {
    private GeneratedResourceRuntime.Facts f(int gauge,int revision,long now){return new GeneratedResourceRuntime.Facts(true,true,true,true,gauge,true,revision,now);}
    private GeneratedResourceRuntime owned(int required){var r=new GeneratedResourceRuntime();assertEquals(GeneratedResourceRuntime.Action.OPEN,r.tick(required,new GeneratedResourceRuntime.Facts(true,true,false,false,-1,false,-1,0)));return r;}
    @Test void prefilledToolRequiresGaugeAndObservedCloseBeforeCompletion(){var r=owned(3456);assertEquals(GeneratedResourceRuntime.Action.CLOSE,r.tick(3456,f(3456,1,0)));assertEquals(GeneratedResourceRuntime.Action.CLOSE,r.tick(3456,f(3456,1,100)));assertEquals(GeneratedResourceRuntime.Action.COMPLETE,r.tick(3456,new GeneratedResourceRuntime.Facts(true,true,false,false,-1,false,-1,200)));}
    @Test void transferRequiresLaterRevisionAndGaugeGrowthNotPredictedClicks(){var r=owned(64);assertEquals(GeneratedResourceRuntime.Action.TRANSFER,r.tick(64,f(0,1,0)));assertEquals(GeneratedResourceRuntime.Action.NONE,r.tick(64,f(64,1,50)));assertEquals(GeneratedResourceRuntime.Action.NONE,r.tick(64,f(0,2,100)));assertEquals(GeneratedResourceRuntime.Action.CLOSE,r.tick(64,f(64,2,200)));}
    @Test void missingResourcesNameActualAcquisitionBranchAndWrongMenuCannotAct(){var r=owned(64);assertEquals(GeneratedResourceRuntime.Action.STOP,r.tick(64,new GeneratedResourceRuntime.Facts(true,true,true,true,0,false,1,0)));assertTrue(r.status().contains("BUY_RESOURCE"));assertEquals(GeneratedResourceRuntime.Action.STOP,owned(64).tick(64,new GeneratedResourceRuntime.Facts(true,true,true,false,64,true,1,0)));}
    @Test void gaugeBindingIsExactAndRejectsDuplicatePlayerOrMalformedValues(){var b=new GeneratedResourceBinding("minecraft:blaze_rod","minecraft:dirt","Bound Tool","Resources","Stored: ");var slot=new MenuSnapshot.Slot(10,"Resources",List.of("Stored: 3,456"),false);assertEquals(3456,b.storedCount(new MenuSnapshot(1,"Bound Tool",List.of(slot))).orElseThrow());assertTrue(b.storedCount(new MenuSnapshot(1,"Other Tool",List.of(slot))).isEmpty());assertTrue(b.storedCount(new MenuSnapshot(1,"Bound Tool",List.of(slot,slot))).isEmpty());assertTrue(b.storedCount(new MenuSnapshot(1,"Bound Tool",List.of(new MenuSnapshot.Slot(10,"Resources",List.of("Stored: 3456"),true)))).isEmpty());assertThrows(IllegalArgumentException.class,()->GeneratedResourceBinding.decode(""));}
    @Test void openingUsesSourceSelectLookAwayAndUseOrderWithBoundTimeout(){var r=new GeneratedResourceRuntime();assertEquals(GeneratedResourceRuntime.Action.SELECT,r.tick(64,new GeneratedResourceRuntime.Facts(false,false,false,false,-1,false,-1,0)));assertEquals(GeneratedResourceRuntime.Action.AIM_AWAY,r.tick(64,new GeneratedResourceRuntime.Facts(true,false,false,false,-1,false,-1,100)));assertEquals(GeneratedResourceRuntime.Action.OPEN,r.tick(64,new GeneratedResourceRuntime.Facts(true,true,false,false,-1,false,-1,200)));assertEquals(GeneratedResourceRuntime.Action.NONE,r.tick(64,new GeneratedResourceRuntime.Facts(true,true,false,false,-1,false,-1,300)));assertEquals(GeneratedResourceRuntime.Action.STOP,r.tick(64,new GeneratedResourceRuntime.Facts(true,true,false,false,-1,false,-1,3301)));}
    @Test void optionalSourceToolAndResourceNamesStayExplicitInsteadOfInvented(){var b=GeneratedResourceBinding.decode("{\"toolItem\":\"minecraft:blaze_rod\",\"resourceItem\":\"minecraft:dirt\",\"menuTitle\":\"Tool\",\"gaugeLabel\":\"Gauge\",\"countPrefix\":\"Stored: \",\"toolName\":\"Captured tool\",\"resourceName\":\"Captured material\"}");assertEquals("Captured tool",b.toolName());assertEquals("Captured material",b.resourceName());assertEquals("",new GeneratedResourceBinding("minecraft:blaze_rod","minecraft:dirt","Tool","Gauge","Stored: ").toolName());}
    @Test void preexistingSameTitleToolMenuCannotBeAdoptedAsAnOwnedReceipt(){var r=new GeneratedResourceRuntime();assertEquals(GeneratedResourceRuntime.Action.STOP,r.tick(3456,f(3456,1,0)));assertTrue(r.status().contains("Unowned"));}
}
